def case_match(word, pat):
    # Match word against pattern pat with * and ? only (no []), escape [, ], etc. literally
    # Convert pat to regex: * => .*, ? => ., escape all else (including [, ], (, ), |, etc. literally, except * and ?)
    import re as _re
    regex=""
    for ch in pat:
        if ch=='*':
            regex+=".*"
        elif ch=='?':
            regex+="."
        else:
            regex+=_re.escape(ch)
    regex="^"+regex+"$"
    try:
        return _re.match(regex, word) is not None
    except:
        return word==pat

